const gitcalendar = new Vue({
    el: '#gitcalendar',
    data: {
        simplemode: true, //打开时使用canvas绘制gitgitcalendar，关闭时使用svg绘制gitgitcalendar
                          //canvas：dom数少，但图像会发生模糊，自适应一般  svg：dom数多，图像清晰，自适应更佳

        user: 'insistgang', //这里填写你的github用户名

        fixed: 'fixed',
        px: 'px',
        x: '',
        y: '',
        span1: '',
        span2: '',
        month: ['一月', '二月', '三月', '四月', '五月', '六月', '七月', '八月', '九月', '十月', '十一月', '十二月'],
        monthchange: [],
        oneyearbeforeday: '',
        thisday: '',
        amonthago: '',
        aweekago: '',
        weekdatacore: 0,
        datacore: 0,
        total: 0,
        datadate: '',
        data: [],
        positionplusdata: [],
        firstweek: [],
        lastweek: [],
        beforeweek: [],
        thisweekdatacore: 0,
        mounthbeforeday: 0,
        mounthfirstindex: 0,
        crispedges: 'crispedges',
        thisdayindex: 0,
        amonthagoindex: 0,
        amonthagoweek: [],
        firstdate: [],
        first2date: [],
        montharrbefore: [],
        monthindex: 0,
        purple: ['#ebedf0', '#fdcdec', '#fc9bd9', '#fa6ac5', '#f838b2', '#f5089f', '#c4067e', '#92055e', '#540336', '#48022f', '#30021f',],
        green: ['#ebedf0', '#f0fff4', '#dcffe4', '#bef5cb', '#85e89d', '#34d058', '#28a745', '#22863a', '#176f2c', '#165c26', '#144620'],
        blue: ['#ebedf0', '#f1f8ff', '#dbedff', '#c8e1ff', '#79b8ff', '#2188ff', '#0366d6', '#005cc5', '#044289', '#032f62', '#05264c',],
        color: ['#ebedf0', '#fdcdec', '#fc9bd9', '#fa6ac5', '#f838b2', '#f5089f', '#c4067e', '#92055e', '#540336', '#48022f', '#30021f',]
    },
    methods: {
        selectStyle(data, event) {
            document.querySelector('.angle-wrapper').style.display = 'block'
            this.span1 = data.date;
            this.span2 = data.count;
            this.x = event.clientX - 100;
            this.y = event.clientY - 60
        },
        outStyle() {
            document.querySelector('.angle-wrapper').style.display = 'none'
        },
        thiscolor(x) {
            if (x === 0) {
                let i = parseInt(x / 2);
                return this.color[0]
            } else if (x < 2) {
                return this.color[1]
            } else if (x < 20) {
                let i = parseInt(x / 2);
                return this.color[i]
            } else {
                return this.color[9]
            }
        },
    }
