```c
void selection_sort(int a[], int len) {
	int i,j;
	for (i = 0 ; i < len - 1 ; i++) {
		int min = i;
		for (j = i + 1; j < len; j++)
			if (a[j] < a[min])
				min = j;
		if(min!=i){
			int t=a[min];
			a[min]=a[i];
			a[i]=t;
		}
	}
}
