		gets(name);
		if(strlen(name)==0)
			break;
		strcat(name,"\n");
		rewind(fp);
		flag=1;
		while(flag&&(fgets(data,30,fp))!=NULL){
			if(strcmp(data,name)==0){
				flag=0;
