char *getword (FILE *fp)
{ 
	int i=0;
	char c;
	while((c=getc(fp)) != EOF && (c==' '||c=='\t'||c=='\n'));
	if(c==EOF) 
		return (NULL) ;
	else 
		buf[i++]=c;
	while((c = fgetc(fp))!=EOF&& c!= ' ' && c!= '\t' && c!= '\n' )
		buf[i++] = c;
		buf[i]= '\0';
	return(buf);
}
void lookup(char *p)
{ 
	int i;
	char *q, *s;
	for(i=0;i<num;i++){ 
		q = &keyword[i].word[0] ;
		s=p;
	while( *s && (*s==*q) ){ 
		s++; q++;
	}
	if( *s==*q ){ 
		keyword[i].count++;
		break;
	}}
	return;
}
int main()
