### 后缀表达式

编写函数，求后缀表达式的值，后缀表达式存在一个字符数组exp中，假设后缀式的数字都只有一位。

```cpp
#include<iostream>
#include<cstring>
using namespace std;
const int N=100010;
double op(int a,char op,int b){
    if(op=='+') return a+b;
    if(op=='-') return a-b;
    if(op=='*') return a*b;
    if(op=='/') {
        if(b==0){
            return 0;
        }
        return (a*1.0)/(b*1.0);
    }
}
double fun(char exp[]){
    int len=strlen(exp);
    double stack[N];
    int top=-1;
    for(int i=0;i<len;i++){
        if(exp[i]>='0'&&exp[i]<='9')
            stack[++top]=exp[i]-'0';
        else{
            double a,b,c;
            b=stack[top--];
            a=stack[top--];
            c=op(a,exp[i],b);
            stack[++top]=c;
        }
    }
    return stack[top];
}
int main(){
