int Count_k_Leaf(BiTree T,int k){
    if(T==NULL) return 0;
    BiTree q[MAX_SIZE];
    int front=0,rear=0;
    int level=0,count;//分别表示层次值，第k层结点数
    BiTree p=T;
    q[++rear]=p;
