        if(level==k) cout=rear-front;
        int l=front+1,r=rear;
        for(int i=l;i<=r;i++){//对level层结点进行遍历
            if(q[i]->lchild!=NULL) q[++rear]=q[i]->lchild;
            if(q[i]->rchild!=NULL) q[++rear]=q[i]->rchild;
