	ArcNode *next;//指针
};
struct VNode{	//顶点结构
	int data;//顶点信息
	ArcNode *firstarc;
};
struct AGraph{	//表
	VNode adjlist[Maxn];//存储所有顶点链表  存了所有顶点 以及他们所指向的边
