//先序遍历
void PreOrder2(BiTree T){
    BiTree Stack[MAX_SIZE];//初始化栈和遍历指针
    int top=0;
    BiTree p=T;
    while(p!=NULL||top>0){//栈不为空或p不为空时循环
        while(p!=NULL){ 
            visit(p);//访问当前结点
            Stack[++top]=p;//当前结点入栈
            p=p->lchild;//左孩子不为空一直往左走
        }
        p=Stack[top--];//栈顶元素出栈
        p=p->rchild;//向右子树走即p赋值为当前结点的右子树
    }
}
