                    w1=HT[j].weight;
                    p1=j;
                }else if(HT[j].weight<w2){
                    w2=HT[j].weight;
                    p2=j;
                }
            }//找到权值最小的两个值及其下标
        }
        HT[k].lchild=p1;
        HT[k].rchild=p2;
        HT[k].weight=w1+w2;
        HT[p1].parent=k;
        HT[p2].parent=k;
    }
}
void Huff_coding(unsigned n,HTNode HT[],unsigned m){
    int k,sp,fp;
