### 非递归遍历

```cpp
//先序遍历
void PreOrder2(BiTree T){
    BiTree Stack[MAX_SIZE];//初始化栈和遍历指针
    int top=0;
    BiTree p=T;
    while(p!=NULL||top>0){//栈不为空或p不为空时循环
        while(p!=NULL){ 
            visit(p);//访问当前结点
            Stack[++top]=p;//当前结点入栈
            p=p->lchild;//左孩子不为空一直往左走
        }
        p=Stack[top--];//栈顶元素出栈
        p=p->rchild;//向右子树走即p赋值为当前结点的右子树
    }
}
//中序遍历
void InOrder2(BiTree T){
    BiTree Stack[MAX_SIZE];//初始化 栈 和 遍历指针
    int top=0;    
    BiTree p=T;
    while(p!=NULL||top>0){//栈不空或p不空时循环
        while(p!=NULL){//一直往左走
            Stack[++top]=p;//当前结点入栈
            p=p->lchild;//左孩子不为空一直往左走
        }
        p=Stack[top--];//栈顶元素出栈 并访问
        visit(p);
        p=p->rchild;////向右子树走即p赋值为当前结点的右子树
    }
}

//后续遍历LRN 逆序 NRL 先根遍历NLR 
void PostOrder2(BiTree T){
    BiTree Stack1[MAX_SIZE];
    BiTree Stack2[MAX_SIZE];
    int top1=0,top2=0;
    BiTree p=T;
    while(p!=NULL||top1>0){
        while(p!=NULL){
            Stack[++top1]=p;
            Stack[++top2]=p;//存储后序列
            p=p->rchild;
        }
        p=Stack1[top--];
        p=p->lchild;
    }
    //Stack2中的元素依次出栈就是后续遍历。
    while(top2>0){
        visit(Stack2[top2]);
        top2--;
    }
}
void PostOrder2(BiTree T) {
    BiTree Stack[MAX_SIZE];
    BiTree p = T, r = NULL;// 遍历指针 最近访问过指针
    int top = 0;
    while (p !=NULL || top > 0) {
        while (p != NULL) { //一直向左走
            Stack[++top] = p;
            p = p->lchild;
        }//向右走
        p = Stack[top]; //获取栈顶元素
        if (p->rchild && p->rchild != r) {//若右子树存在且未被访问过
            p = p->rchild; //转向右子树
            } else { //否则，弹出结点并访问
                p = Stack[top--];
                visit(p);//访问结点
                r = p; //记录最近访问过的结点
                p = NULL;//结点访问完，重置p指针
            }
        }
}
// 注意：每次出栈访问完一个结点就相当于遍历完以该结点为根的子树，需将p置NULL

