using namespace std;
int prime(int x){
    if(x<=3)return 1;
    for(int i=2;i<=sqrt(x);i++){
        if(x%i==0)
            return 0;
    }
    return 1;
}
int main(){
    int n;
    cin>>n;
    for(int i=2;i<(n/2);i++){
        if(prime(i)&&prime(n-i)){
