```cpp
#include<iostream>
#include<cstring>
using namespace std;
int main(){
    string a;
    getline(cin,a);
    int len=a.length();
    for(int i=0;i<len/2;i++){
        if(a[i]==a[len-1-i]){
            continue;
        }else{
            cout<<"不是回文串"<<endl;
            return 0;
        }
    }
    cout<<"是回文串"<<endl;
    return 0;
}

#include<iostream>
#include<cstring>
using namespace std;
const int N=100010;
int main(){
    char str[N];
    scanf("%s",str);
    int flag=1;
    int len=strlen(str);
    for(int i=0,j=len-1;i<=len/2;i++,j--){
        if(str[i]!=str[j]){
            flag=0;
            break;
        }
    }
    if(flag){
        cout<<"是回文串";
    }else{
        cout<<"不是回文串";
    }
    return 0;
}

