数组调整，左奇右偶

```cpp
#include<iostream>
using namespace std;
const int N=100010;
int main(){
    int a[N];
    int n;
    cin>>n;
    for(int i=0;i<n;i++){
        cin>>a[i];
    }
    int i=0;
    int j=n-1;
    while(i<j){
        while(i<j&&a[j]%2==0){
            j--;
        }
        while(i<j&&a[i]%2==1){
            i++;
        }
        if(i<j){
            swap(a[i],a[j]);
        }
    }

    for(int i=0;i<n;i++){
        cout<<a[i]<<" ";
    }
    return 0;
}

