int max_ele(int a,int b){//最大公约数
    int result=1,minn;
    minn=min(a,b);
    for(int i=minn;i>=1;i--){
        if(a%i==0&&b%i==0){
            result=i;
            break;
        }
    }
    return result;
}
int min_time(int a,int b){//最大公约数
    int result,maxn;
    maxn=max(a,b);
    for(int i=maxn;i<=a*b;i++){
        if(i%a==0&&i%b==0){
            result=i;
            break;
        }
    }
    return result;
}
