void ListChooseSort(LNode *head){
    //用选择法进行排序
    LNode *p,*q;
    LNode *temp;
    for(p=head->next;p->next;p=p->next){//从第一个结点开始，到倒数第二个结点结束
        temp=p;
        for(q=p->next;q;q=q->next){//从p的下一个结点开始，到倒数第二个结点结束
