double fun(double x,int n){
    if(n==0)//递归结束条件
        return 1;
    double half;
    if(n%2==1){//递归转移方程
        half=fun(x,n/2);//x的n/2次方
        return x*half*half;
    }else{
        half=fun(x,n/2);
        return half*half;
    }
}
double pow(double x,int n){
    double result=fun(x,n);
    if(n<0)
        result=1/result;
    return result;
}

int pow(int x,int n){
    int t=1;
    while(n){
        if(n%2==1){
            n=n-1;
            t*=x;
        }
        x*=x;
        n/=2;
    }
    return t;
}
