```cpp
void Find(char a[],int n,char e){
    //n为数组长度，e为要查找的元素
    for(int i=0;i<n;i++){
        if(a[i]==e){
            //找到元素之后
            for(int j=i-1;j>=0;j--){
                a[j+1]=a[j];//i-1位置之前的所有结点后移
            }
            a[0]=e;
        }
    }
}

struct LNode{
    char data;//数据域，保存结点的值
    struct LNode *next;//指针域
};
void Find(LNode *L,char e){
    LNode *p=L->next,*q=L;
    while(p!=NULL&&p->data!=e){
        p=p->next;
        q=q->next;
    }
    if(p->data==e){
        q->next=p->next;//删除p
        p->next=L->next;//将p移动到头结点
        L->next=p;
    }else{
        cout<<"所要查找的结点不存在！！"<<endl;
    }
}

