### 2. 只用一个二叉树根节点指针T，用高效率方法，计算

1. 所有结点个数
2. 所有叶子结点个数
3. 所有满结点个数/所有满状态结点个数

```cpp
/*
递归函数实现的二叉树遍历算法是很低效的，我们采用线索二叉树算法。Tnorder算法输出的a,b,c为相应的结点个数、叶子结点个数和满状态结点个数
*/
struct TBTNode{
    char data;
    int ltag,rtag;//线索标记
    struct TBTNode *lchild;
    struct TBTNode *rchild;
}
void Tnorder(TBTNode *T){
    int a=0,b=0,c=0;
    for(TBTNode *p=Frist(T);p!=NULL;p=Next(p)){
        //遍历中序线索树
        a++;
        if(p->ltag==1&&p->rtag==1)
            b++;
        if(p->ltag==0&&p->rtag==0)
            c++;
    }
    cout<<"所有结点个数："<<a<<endl;
    cout<<"叶子结点个数："<<b<<endl;
    cout<<"满状态结点个数："<<c<<endl;
}
TBTNode *Frist(TBTNode *p){
    //求以p为根的中序线索二叉树，中序序列下的第一个结点的算法
    while(p->ltag==0){
        p=p->lchild;
    }
    return p;
}
TBTNode *Next(TBTNode *p){
    //求中序线索二叉树中结点p在中序下的后继结点的算法
    if(p->rtag==0)
        return Frist(p->rchild);
    return p->rchild;//rtag=1,直接返回后继线索
}

```

### 简述如何不用递归实现归并排序，并实现过程

![](../../images/1.png)

```cpp
/*
将数组中的相邻元素两两配对，用Merge()函数将他们排序，构成n/2组长度为2的排序好的子数组段，然后再将他们合并成长度为4的子数组段，如此继续下去，直至整个数组排好序。
*/
#include<iostream>
#include<algorithm>
using namespace std;
#define maxn 100
int num[maxn];
template<class Type>
void Merge(Type a[],Type b[],int left,int mid,int right){
    int i=left;
    int j=mid+1;
    int k=left;
    while(i<=mid&&j<=right){
        if(a[i]<a[j])
            b[k++]=a[i++];
        else
            b[k++]=a[j++]
    }
    if(i>mid)
        for(int z=j;z<=right;z++)
            b[k++]=a[z];
    else
        for(int z=i;z<=mid;z++)
            b[k++]=a[z];
}
//合并大小为s的相邻子数组
void MergePass(Type x[],Type y[],int s,int n){
    int i=0;
    while(i+2*s-1<n){
        Merge(x,y,i,i+s-1,i+2*s-1);
        //合并大小为s的相邻2段子数组
        i+=2*s;
    }
    if(i+s<n)
//剩下的元素个数m满足:s<=m<2*s
        Merge(x,y,i,i+s-1,n-1);
    else
//剩下的元素个数m满足：m<s
        Merge(x,y,i,i,n-1);
}
template<class Type>
void MergeSort(Type c[],int n){
    Type *d=new Type[n];
    int s=1;
    while(s<n){
        MergePass(c,d,s,n);//合并到数组d
        s+=s;
        //就像图中有序的两个合并为一个
        MergePass(d,c,s,n);//合并到数组c
        s+=s;
    }
delete[] b;
}
int main(){
    int n;
    while(cin>>n){
        for(int i=0;i<n;i++)
            cin>>num[i];
        MergeSort(num,n);
        for(int i=0;i<n;i++)
            cout<<num[i]<<endl;
    }
    return 0;
}
