输出

3 3,4 2,5 2，6 2，7 1，8 1,9 1

```cpp
#include<stdio.h>
typedef struct E{
    int data;//数据域，保存结点的值
    int times;//统计次数
}E;
void tongji(int a[],int n){
    //n代表数组长度 初始化
    E arr[1000],m;
    arr[0].data=a[0];
    arr[0].times=1;
    int i=1,j=0;//i是原数组下标，j是新数组下标
    int p=0,q=0,r=0;
    for(int s=1;s<1000;s++){
        arr[s].times=-1;//初始化
    }
    while(i<n){
        j=0;
        while(a[i]!=arr[j].data&&arr[j].times!=-1) j++;
        if(arr[j].times==-1){
            //无相同元素
            arr[j].data=a[i];
            arr[j].times=1;
            p=j,q=j;
            //调换，次数大的在前面，次数相同的数字小的在前
            while(arr[p].times>arr[p-1].times&&p>0){
                m=arr[p];
                arr[p]=arr[p-1];
                arr[p-1]=m;
                p--;
            }
            while(arr[q].times==arr[q-1].times&&arr[q].data<arr[q-1].data&&q>0){
                m=arr[q];
                arr[q]=arr[q-1];
                arr[q-1]=m;
                q--;
            }
        }
        else{
            //相同元素
            arr[j].times++;
            p=j,q=j;
            //调换，次数大的在前面，次数相同的数字小的在前
            while(arr[p].times>arr[p-1].times&&p>0){
                m=arr[p];
                arr[p]=arr[p-1];
                arr[p-1]=m;
                p--;
            }
            while(arr[q].times==arr[q-1].times&&arr[q].data<arr[q-1].data&&q>0){
                m=arr[q];
                arr[q]=arr[q-1];
                arr[q-1]=m;
                q--;
            }
        }
        i++;
        if(r<j) r=j;
    }
    //输出到文件
    FILE *fp;
    fp=fopen("example.txt","w");
    for(int i=0;i<=r;i++)
        fprintf(fp,"%d %d",arr[i].data,arr[i].times);
    fclose(fp);
}
int main(){
    int n,i;
    bool flag=true;
    cin>>n;
    if(n<0||n>1000)
        cout<<"输入错误！"<<endl;
    else{
        int arr[100];
        for(i=0;i<n;i++) cin>>arr[i];
        for(i=0;i<n;++i){
            if(arr[i]<0||arr[i]>1000){
                flag=false;
                break;
            }
        }
        if(flag)
            tongji(arr,n);
        else
