        while(i<j&&arr[i]<=num)i++;//从左边扫找到第一个大于标兵的点
        swap(arr,i,j);			   //交换他们
    }
    swap(arr,left,j);//两指针相遇后，就找到了下一次划分的界限，把找到的分界线上的值与标兵换一下
    qsort(arr,left,j-1);//分界线左边继续划分
    qsort(arr,j+1,right);//分界线右边继续划分
}
```

